import test from'node:test';import assert from'node:assert/strict';import http from'node:http';import fs from'node:fs';import os from'node:os';import path from'node:path';
import {observeSpot,createObservationSession}from'../observer.mjs';import {transport}from'../transport.mjs';import {quoteSpot}from'../quote.mjs';import {demoInputs,DEMO_MARKET}from'../demo.mjs';import {NOW,providerServer,grpc,marketBytes}from'./fixtures.mjs';import {runSpotCli}from'../../spot.mjs';
const selection=(endpoint,provider='injective')=>({provider,endpoint,network:'synthetic',...(provider==='injective'?{marketId:DEMO_MARKET}:{pairIndex:1})});
const options={now:()=>NOW};
for(const provider of ['injective','hypercore'])test(`${provider}: actual HTTP endpoint to decoded book and estimate`,async t=>{const s=await providerServer(t),b=await observeSpot(selection(s.endpoint,provider),options);assert.equal(b.market.provider,provider);assert.equal(s.requests.length,3);assert.ok(s.requests.every(r=>r.method==='POST'&&!r.headers.authorization&&!r.headers.cookie));const q=quoteSpot(b,{side:'sell-base',inputAtomic:provider==='injective'?'1000000000000000000':'100000000'},{now:NOW});assert.equal(q.quoteNotionalAtomic,'9500000');assert.equal(q.executable,false);});
test('metadata changes across book read are rejected',async t=>{const s=await providerServer(t,{modify:(x,kind,n)=>{if(kind==='Market'&&n===2)x.market.takerFeeRate='0.005';}});await assert.rejects(observeSpot(selection(s.endpoint),options),/MARKET_CHANGED/);});
test('selected HyperCore token mapping changes are rejected',async t=>{const s=await providerServer(t,{modify:(x,kind,n)=>{if(kind==='spotMeta'&&n===2)x.hyperMeta.tokens[1].tokenId='0x'+'33'.repeat(16);}});await assert.rejects(observeSpot(selection(s.endpoint,'hypercore'),options),/MARKET_CHANGED/);});
test('old book timestamps cannot be replaced by request time',async t=>{const s=await providerServer(t,{now:NOW-60000});await assert.rejects(observeSpot(selection(s.endpoint),options),/STALE/);});
test('explicit remote disclosure consent required before any fetch',async()=>{let calls=0;await assert.rejects(observeSpot(selection('https://example.com'),{fetchImpl:()=>{calls++;}}),/REMOTE_DISCLOSURE/);assert.equal(calls,0);});
test('consent pins exact https origin; wallet/API credentials forbidden',()=>{for(const endpoint of ['http://example.com','https://name:pass@example.com','https://example.com/other','https://example.com/?key=secret'])assert.throws(()=>transport(endpoint,{access:{mode:'explicit-remote',allowedOrigins:['https://example.com']}}));});
test('read client has no arbitrary RPC or transaction method',async()=>{let called=false;const r=transport('http://127.0.0.1:1234',{fetchImpl:()=>{called=true;}});await assert.rejects(r('sendTransaction',{}),/READ_ONLY/);assert.equal(called,false);});
test('redirect response is rejected without substitution',async()=>{const response=new Response('{}',{headers:{'content-type':'application/json'}});Object.defineProperty(response,'redirected',{value:true});await assert.rejects(transport('http://127.0.0.1:1234',{fetchImpl:async()=>response})('spotMeta'),/REDIRECT/);});
test('malformed JSON, duplicate members and lossless unsafe numeric fields rejected by boundary',async()=>{for(const text of ['{"tokens":[],"tokens":[]}','{"__proto__":{}}','{','{"tokens":1e9999,"universe":[]}']){
 const r=transport('http://127.0.0.1:1234',{fetchImpl:async()=>new Response(text,{headers:{'content-type':'application/json'}})});
 if(text.includes('1e9999')){const raw=await r('spotMeta');assert.equal(raw.tokens,'1e9999');}else await assert.rejects(r('spotMeta'));
 }});
test('gRPC error status on HTTP 200 is not success',async()=>{await assert.rejects(observeSpot(selection('http://127.0.0.1:1234'),{...options,fetchImpl:async()=>new Response(grpc(marketBytes(),'13'),{headers:{'content-type':'application/grpc-web+proto'}})}),/GRPC_STATUS/);});
test('body resource limit and unexpected content type rejected',async()=>{for(const response of [()=>new Response('a',{headers:{'content-type':'application/json','content-length':'99999999'}}),()=>new Response('{}',{headers:{'content-type':'text/html'}})])await assert.rejects(transport('http://127.0.0.1:1',{fetchImpl:async()=>response()})('spotMeta'));});
test('cancel interrupts a fetch implementation which ignores its signal',async()=>{const c=new AbortController(),r=transport('http://127.0.0.1:1',{signal:c.signal,fetchImpl:()=>new Promise(()=>{})});const p=r('spotMeta');c.abort();await assert.rejects(p,/ABORTED/);});
test('session stop discards a late response; new session can still succeed',async t=>{const s=await providerServer(t,{delay:20}),session=createObservationSession(),p=session.run(selection(s.endpoint),options);session.cancel();await assert.rejects(p);const b=await session.run(selection(s.endpoint),options);assert.equal(b.executable,false);});
test('HTTP request body and options contain no cookie, key, signing authority or redirects',async()=>{let seen;const req=transport('https://example.com',{access:{mode:'explicit-remote',allowedOrigins:['https://example.com']},fetchImpl:async(u,o)=>{seen={u,o};return new Response('{}',{headers:{'content-type':'application/json'}});}});await req('spotMeta');assert.equal(seen.u,'https://example.com/info');assert.deepEqual(JSON.parse(seen.o.body),{type:'spotMeta'});assert.equal(seen.o.credentials,'omit');assert.equal(seen.o.redirect,'error');});
test('CLI default demo is network-free and its output is not executable',async()=>{const x=JSON.parse(await runSpotCli([],{now:()=>NOW}));assert.equal(x.mode,'synthetic-demo');assert.equal(x.estimate.estimatedOutputAfterTradingFeeAtomic,'9481000');assert.equal(x.executionEnabled,false);});
test('CLI performs real loopback gRPC request and cannot overwrite output',async t=>{const s=await providerServer(t);const d=fs.mkdtempSync(path.join(os.tmpdir(),'realdex-spot-'));t.after(()=>fs.rmSync(d,{recursive:true,force:true}));const file=path.join(d,'result.json'),a=['--endpoint',s.endpoint,'--network','test','--market',DEMO_MARKET,'--output',file];await runSpotCli(a,{now:()=>NOW});assert.ok(fs.existsSync(file));await assert.rejects(runSpotCli(a,{now:()=>NOW}));});
test('CLI rejects unknown flags and duplicate options',async()=>{for(const args of [['--send','1'],['--amount','1','--amount','2'],['--provider']])await assert.rejects(runSpotCli(args),/ARGUMENTS/);});
test('selection refuses secret-like and arbitrary fields rather than forwarding them',async()=>{await assert.rejects(observeSpot({...selection('http://127.0.0.1:1'),privateKey:'not-a-key'},options),/SELECTION/);});
